public class ClassicSingleton {
    private static ClassicSingleton instance;
    private ClassicSingleton() { }
    public static ClassicSingleton getInstance() {
        if (instance == null) instance = new ClassicSingleton();
        return instance;
    }
}
Constructor<ClassicSingleton> ctor = ClassicSingleton.class.getDeclaredConstructor();
ctor.setAccessible(true);
ClassicSingleton second = ctor.newInstance();
System.out.println(second == ClassicSingleton.getInstance());

class TeamBuilder {
    private List<String> members = new ArrayList<>();
    TeamBuilder addMember(String m) { members.add(m); return this; }
    Team build() { return new Team(members); } // no defensive copy!
}
class Team {
    List<String> members;
    Team(List<String> members) { this.members = members; }
}

TeamBuilder builder = new TeamBuilder().addMember("Ann");
Team team1 = builder.build();
builder.addMember("Bo");
System.out.println(team1.members);

