public class Holder {
    private static class InstanceHolder {
        static final Holder INSTANCE = new Holder();
    }
    public static Holder getInstance() {
        return InstanceHolder.INSTANCE;
    }
}

class Range implements Iterator<Integer> {
    int current, end;
    Range(int start, int end) { this.current = start; this.end = end; }
    public boolean hasNext() { return current < end; }
    public Integer next() { return current++; }
}
Iterator<Integer> it = new Range(0, 3);
while (true) {
    System.out.println(it.next());
}

interface Coffee { double cost(); }
class SimpleCoffee implements Coffee { public double cost() { return 2.0; } }
class MilkDecorator implements Coffee {
    Coffee inner;
    MilkDecorator(Coffee c) { this.inner = c; }
    public double cost() { return inner.cost() + 0.5; }
}

Coffee order = new MilkDecorator(new MilkDecorator(new SimpleCoffee()));
System.out.println(order.cost());

